/*
	CloudCheats 2026 theme
	Visual direction based on the supplied VACBAN references.
*/

:root {
	--cc-bg: #101019;
	--cc-bg-soft: #151521;
	--cc-surface: #1e1e2d;
	--cc-surface-raised: #252537;
	--cc-border: rgba(146, 150, 255, .14);
	--cc-border-strong: rgba(146, 150, 255, .28);
	--cc-text: #f7f8fc;
	--cc-text-muted: #a1a5b7;
	--cc-accent: #009ef7;
	--cc-accent-2: #6c63ff;
	--cc-success: #50cd89;
	--cc-warning: #ffc700;
	--cc-danger: #f1416c;
	--cc-radius-sm: 8px;
	--cc-radius: 12px;
	--cc-radius-lg: 18px;
	--cc-shadow: 0 18px 55px rgba(0, 0, 0, .28);
}

html {
	color-scheme: dark;
	background: var(--cc-bg);
}

body {
	font-family: Poppins, Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
	font-size: 15px;
	line-height: 1.6;
	color: var(--cc-text);
	background:
		radial-gradient(circle at 12% -10%, rgba(0, 158, 247, .16), transparent 34rem),
		radial-gradient(circle at 88% 0%, rgba(108, 99, 255, .12), transparent 30rem),
		var(--cc-bg);
}

a {
	color: #68c7ff;
	transition: color .18s ease, opacity .18s ease;
}

a:hover,
a:focus {
	color: #a7dfff;
}

.p-pageWrapper {
	background: transparent;
}

.p-header {
	background: rgba(16, 16, 25, .92);
	border-bottom: 1px solid var(--cc-border);
	box-shadow: 0 10px 35px rgba(0, 0, 0, .22);
	backdrop-filter: blur(16px);
}

.p-header-logo a {
	color: var(--cc-text);
	font-weight: 800;
	letter-spacing: -.03em;
}

.p-header-logo img {
	display: none;
}

.p-header-logo a::before {
	content: "CloudCheats";
	display: inline-block;
	font-size: clamp(1.35rem, 3vw, 1.8rem);
	font-weight: 800;
	letter-spacing: -.045em;
	color: #fff;
	text-shadow: 0 0 24px rgba(0, 158, 247, .24);
}

.p-header-logo a::after {
	content: ".cc";
	font-size: .82rem;
	font-weight: 700;
	color: var(--cc-accent);
}

.p-nav {
	background: rgba(21, 21, 33, .94);
	border-bottom: 1px solid var(--cc-border);
}

.p-nav-list .p-navEl,
.p-navgroup-link {
	border-radius: var(--cc-radius-sm);
}

.p-nav-list .p-navEl.is-selected,
.p-nav-list .p-navEl:hover,
.p-navgroup-link:hover {
	background: rgba(0, 158, 247, .12);
	color: #fff;
}

.p-sectionLinks {
	background: rgba(30, 30, 45, .96);
	border-bottom: 1px solid var(--cc-border);
}

.p-body-inner {
	max-width: 1320px;
}

.p-body-header {
	margin-bottom: 24px;
}

.p-title-value {
	font-size: clamp(1.65rem, 3vw, 2.35rem);
	font-weight: 750;
	letter-spacing: -.035em;
	color: #fff;
}

.p-description,
.formRow-explain,
.formRow-hint,
.contentRow-minor,
.pairs > dt {
	color: var(--cc-text-muted);
}

.block-container,
.blockMessage,
.overlay,
.menu-content,
.memberHeader,
.message-cell,
.structItemContainer,
.formSubmitRow-bar {
	background: rgba(30, 30, 45, .96);
	border: 1px solid var(--cc-border);
	border-radius: var(--cc-radius);
	box-shadow: var(--cc-shadow);
}

.block-header,
.block-minorHeader,
.block-filterBar,
.menu-header {
	color: #fff;
	background: linear-gradient(135deg, rgba(43, 43, 64, .98), rgba(30, 30, 45, .98));
	border-color: var(--cc-border);
}

.block-header {
	font-size: 1rem;
	font-weight: 700;
	letter-spacing: -.01em;
	padding: 14px 18px;
}

.block-row,
.structItem,
.node,
.dataList-row,
.formRow {
	border-color: var(--cc-border);
}

.block-row:hover,
.structItem:hover,
.dataList-row:hover {
	background: rgba(43, 43, 64, .72);
}

.node + .node,
.structItem + .structItem {
	border-top: 1px solid var(--cc-border);
}

.node-icon,
.structItem-iconContainer,
.contentRow-figure {
	color: var(--cc-accent);
}

.node-title,
.structItem-title,
.contentRow-title {
	font-weight: 650;
}

.input,
.inputGroup-text,
select.input,
textarea.input {
	color: var(--cc-text);
	background: #151521;
	border: 1px solid rgba(161, 165, 183, .2);
	border-radius: var(--cc-radius-sm);
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, .025);
	transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}

.input:focus,
select.input:focus,
textarea.input:focus {
	background: #181825;
	border-color: var(--cc-accent);
	box-shadow: 0 0 0 3px rgba(0, 158, 247, .14);
}

.input::placeholder {
	color: #6f7284;
}

.button,
a.button {
	min-height: 38px;
	padding-inline: 16px;
	font-weight: 650;
	color: #e9eaf2;
	background: #2b2b40;
	border: 1px solid var(--cc-border-strong);
	border-radius: var(--cc-radius-sm);
	box-shadow: none;
	transition: transform .16s ease, background .16s ease, border-color .16s ease, box-shadow .16s ease;
}

.button:hover,
a.button:hover {
	color: #fff;
	background: #35354e;
	border-color: rgba(146, 150, 255, .42);
	transform: translateY(-1px);
}

.button--primary,
a.button--primary,
.button.button--cta,
a.button.button--cta {
	color: #fff;
	background: linear-gradient(135deg, var(--cc-accent), #5271ff);
	border-color: transparent;
	box-shadow: 0 10px 24px rgba(0, 158, 247, .22);
}

.button--primary:hover,
a.button--primary:hover,
.button.button--cta:hover,
a.button.button--cta:hover {
	background: linear-gradient(135deg, #26adfa, #7068ff);
	box-shadow: 0 12px 30px rgba(0, 158, 247, .32);
}

.button--link,
a.button--link {
	color: #68c7ff;
	background: transparent;
}

.menu-content {
	overflow: hidden;
}

.menu-linkRow,
.menu-row {
	color: var(--cc-text);
	border-color: var(--cc-border);
}

.menu-linkRow:hover,
.menu-linkRow.is-selected {
	color: #fff;
	background: rgba(0, 158, 247, .12);
}

.tabs,
.block-tabHeader {
	color: var(--cc-text-muted);
	background: #191927;
	border-color: var(--cc-border);
}

.tabs-tab.is-active,
.block-tabHeader .tabs-tab.is-active {
	color: #fff;
	border-color: var(--cc-accent);
}

.message--post .message-cell--user {
	background: rgba(21, 21, 33, .74);
	border-color: var(--cc-border);
}

.message-attribution,
.message-footer,
.message-userExtras,
.memberHeader-separator {
	border-color: var(--cc-border);
}

.avatar {
	box-shadow: 0 0 0 2px rgba(0, 158, 247, .2);
}

.label {
	border-radius: 999px;
	font-weight: 650;
}

.blockMessage--success {
	color: #9ce7bb;
	background: rgba(80, 205, 137, .1);
	border-color: rgba(80, 205, 137, .3);
}

.blockMessage--warning,
.blockMessage--important {
	color: #ffe58a;
	background: rgba(255, 199, 0, .09);
	border-color: rgba(255, 199, 0, .28);
}

.blockMessage--error {
	color: #ff9ab4;
	background: rgba(241, 65, 108, .1);
	border-color: rgba(241, 65, 108, .3);
}

.pageNav-page > a,
.pageNav-jump,
.pageNavSimple-el {
	color: var(--cc-text-muted);
	background: var(--cc-surface);
	border-color: var(--cc-border);
	border-radius: 7px;
}

.pageNav-page.pageNav-page--current > a {
	color: #fff;
	background: var(--cc-accent);
	border-color: var(--cc-accent);
}

.p-footer {
	color: var(--cc-text-muted);
	background: #0c0c13;
	border-top: 1px solid var(--cc-border);
}

body[data-template="login"] .p-body-pageContent,
body[data-template="register_form"] .p-body-pageContent {
	width: 100%;
	max-width: 680px;
	margin-inline: auto;
}

body[data-template="login"] .block-container,
body[data-template="register_form"] .block-container {
	border-top: 3px solid var(--cc-accent);
	box-shadow: 0 28px 80px rgba(0, 0, 0, .38);
}

body[data-template^="xs_is_"] .block-container {
	border-top: 2px solid rgba(0, 158, 247, .72);
}

.xs_is_copy_code {
	font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
	letter-spacing: .06em;
}

@media (max-width: 650px) {
	body {
		font-size: 14px;
	}

	.p-body-inner {
		padding-inline: 12px;
	}

	.block-container,
	.blockMessage,
	.overlay,
	.menu-content,
	.memberHeader {
		border-radius: 10px;
	}

	.formRow > dt,
	.formRow > dd {
		padding-inline: 14px;
	}

	.button,
	a.button {
		min-height: 42px;
	}
}

@media (prefers-reduced-motion: reduce) {
	*, *::before, *::after {
		scroll-behavior: auto !important;
		transition-duration: .01ms !important;
		animation-duration: .01ms !important;
		animation-iteration-count: 1 !important;
	}
}
